// Regenerates TypeScript types for the contracts this app calls directly (never edit src/api/generated by hand).
// The gateway BFF types come from @afrotransact/api-client (web/packages/api-client/src/generated/gateway-bff.ts).
//   node scripts/generate.mjs          → writes src/api/generated/*.ts
//   node scripts/generate.mjs --check  → exits 1 when the committed output is stale (for CI)
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';

const here = dirname(fileURLToPath(import.meta.url));
const contracts = resolve(here, '../../../../contracts/openapi');
const outDir = resolve(here, '../src/api/generated');
const SPECS = (process.env.SPECS ?? '').split(',').filter(Boolean);
const check = process.argv.includes('--check');
let stale = false;
mkdirSync(outDir, { recursive: true });
for (const spec of SPECS) {
  const src = resolve(contracts, `${spec}.yaml`);
  if (!existsSync(src)) throw new Error(`missing contract ${src}`);
  const ast = await openapiTS(pathToFileURL(src));
  const banner = `// GENERATED from contracts/openapi/${spec}.yaml by openapi-typescript — do not edit by hand.\n// Regenerate with: pnpm --filter ${process.env.npm_package_name ?? '<app>'} generate\n/* eslint-disable */\n\n`;
  const text = banner + astToString(ast);
  const target = resolve(outDir, `${spec}.ts`);
  if (check) {
    if (!existsSync(target) || readFileSync(target, 'utf8') !== text) {
      console.error(`stale: src/api/generated/${spec}.ts — run the generate script`);
      stale = true;
    }
  } else {
    writeFileSync(target, text);
    console.log(`wrote src/api/generated/${spec}.ts`);
  }
}
if (stale) process.exit(1);
